#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const { program } = require('commander');
const chalk = require('chalk');
const { spawnSync } = require('child_process');

// 获取包信息
const packageJson = require('../package.json');

// 配置参数默认值
let sourceDir = 'static';
let outputDir = 'dist';
let configPath = path.resolve('obfuscate.config.js');

// 命令行配置
program
  .name('js-obfuscate')
  .version(packageJson.version)
  .description('JavaScript 代码混淆命令行工具')
  .option('-s, --source <directory>', '源代码目录', sourceDir)
  .option('-o, --output <directory>', '输出目录', outputDir)
  .option('-c, --config <file>', '混淆配置文件路径', configPath)
  .parse(process.argv);

const options = program.opts();
sourceDir = options.source;
outputDir = options.output;
configPath = options.config;

// 获取混淆器路径
function getObfuscatorPath() {
  try {
    // 尝试本地安装
    return require.resolve('javascript-obfuscator/bin/javascript-obfuscator');
  } catch (e) {
    // 尝试全局安装
    try {
      const globalPath = spawnSync('npm', ['root', '-g'], { 
        encoding: 'utf-8',
        windowsHide: true
      }).stdout.trim();

      const globalBin = path.join(globalPath, 'javascript-obfuscator/bin/javascript-obfuscator');
      if (fs.existsSync(globalBin)) return globalBin;

      throw new Error('未找到 javascript-obfuscator');
    } catch (err) {
      throw new Error(`请先安装依赖: npm install javascript-obfuscator${err.message}`);
    }
  }
}

// 递归处理目录
function processDirectory(srcPath) {
  const entries = fs.readdirSync(srcPath, { withFileTypes: true });

  entries.forEach(entry => {
    const srcFullPath = path.join(srcPath, entry.name);
    const relPath = path.relative(sourceDir, srcFullPath);
    const distPath = path.join(outputDir, relPath);

    if (entry.isDirectory()) {
      fs.mkdirSync(distPath, { recursive: true });
      processDirectory(srcFullPath);
    } else {
      fs.mkdirSync(path.dirname(distPath), { recursive: true });

      if (path.extname(entry.name) === '.js') {
        console.log(chalk.blue(`混淆: ${relPath}`));
        const obfuscator = getObfuscatorPath();

        const result = spawnSync('node', [
          obfuscator,
          srcFullPath,
          '--output', path.dirname(distPath),
          '--config', configPath
        ], { 
          stdio: 'inherit',
          windowsHide: true 
        });

        if (result.status !== 0) {
          throw new Error(`混淆失败: ${relPath}`);
        }

        // 处理自动生成的 -obfuscated 后缀
        const obfuscatedFile = path.join(
          path.dirname(distPath),
          `${path.basename(entry.name, '.js')}-obfuscated.js`
        );

        if (fs.existsSync(obfuscatedFile)) {
          fs.renameSync(obfuscatedFile, distPath);
        }
      } else {
        console.log(chalk.green(`复制: ${relPath}`));
        fs.copyFileSync(srcFullPath, distPath);
      }
    }
  });
}

// 主流程
try {
  // 预检
  if (!fs.existsSync(sourceDir)) {
    throw new Error(`源目录不存在: ${sourceDir}`);
  }

  // 检查配置文件
  if (!fs.existsSync(configPath)) {
    console.warn(chalk.yellow(`警告: 配置文件不存在 ${configPath}，将使用默认配置`));
  }

  // 清理目录
  if (fs.existsSync(outputDir)) {
    fs.rmSync(outputDir, { recursive: true, force: true });
  }
  fs.mkdirSync(outputDir, { recursive: true });

  // 开始构建
  console.time('构建耗时');
  processDirectory(sourceDir);
  console.timeEnd('构建耗时');
  console.log(chalk.green(`\n构建成功 → ${path.resolve(outputDir)}`));

} catch (err) {
  console.error(chalk.red('\n错误:'), err.message);
  process.exit(1);
}

